119	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
120	     */
121	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
122	        List<String> missingFields = new ArrayList<>();
123	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
124	            missingFields.add("firstName");
125	        }
126	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
127	            missingFields.add("lastName");
128	        }
129	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
130	            missingFields.add("address");
131	        }
132	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
133	            missingFields.add("city");
134	        }
135	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
136	            missingFields.add("telephone");
137	        }
138	        if (!missingFields.isEmpty()) {
139	            throw new RequiredFieldsMissingException(missingFields);
140	        }
141	    }
