143	    /**
144	     * Normalizes a telephone number by removing every non-digit character and requires the
145	     * result to be exactly 10 digits.
146	     *
147	     * @param telephone the raw telephone value from the request
148	     * @return the 10-digit, digits-only telephone
149	     * @throws InvalidFieldsException if the stripped value is not exactly 10 digits
150	     */
151	    private String normalizeTelephone(String telephone) {
152	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
153	        if (digits.length() != 10) {
154	            throw new InvalidFieldsException(List.of("telephone"));
155	        }
156	        return digits;
157	    }
158	
159	    /**
160	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
161	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
162	     * be a syntactically valid address; the accepted value is returned lower-cased.
163	     *
164	     * @param email the raw email value from the request, may be {@code null}
165	     * @return the lower-cased email, or {@code null} when none was supplied
166	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
167	     */
168	    private String normalizeEmail(String email) {
169	        if (email == null || email.isBlank()) {
170	            return null;
171	        }
172	        String trimmed = email.trim();
173	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
174	            throw new InvalidFieldsException(List.of("email"));
175	        }
176	        return trimmed.toLowerCase(Locale.ROOT);
177	    }
